import{_ as s,o as t,c as n,a4 as e}from"./chunks/framework.B0hSrcZ6.js";const l="/info/04-handoff.webp",o="/info/04-handoff-s1.webp",i="/info/04-handoff-s4.webp",r="/info/04-handoff-s5.webp",m=JSON.parse('{"title":"第 4 章 交代任务：消息、附件与一次好的交接","description":"本章讲解向 Grok Bot 交代任务的方法，解析好请求五要素与附件规格。帮助新手区分长期规则与单次指令，掌握运行干预与审批技巧，避免因需求模糊导致改乱文件。","frontmatter":{},"headers":[],"relativePath":"part1/04-handoff.md","filePath":"part1/04-handoff.md","lastUpdated":1792210948000}'),p={name:"part1/04-handoff.md"};function c(d,a,h,g,u,b){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="第-4-章-交代任务-消息、附件与一次好的交接" tabindex="-1">第 4 章 交代任务：消息、附件与一次好的交接 <a class="header-anchor" href="#第-4-章-交代任务-消息、附件与一次好的交接" aria-label="Permalink to &quot;第 4 章 交代任务：消息、附件与一次好的交接&quot;">​</a></h1><p>需求给得太简短，它容易搜几十个无关网页、改乱文件。<strong>发消息就是给云端电脑交接工作</strong>。</p><ul><li><strong>设死任务边界</strong>并说明附件用途，防止它自作主张</li><li>给出明确指令，换回可直接验收的交付物</li><li>执行中随时插话纠偏，或用语音补充背景</li></ul><p><img src="'+l+'" alt="交代任务：消息、附件与一次好的交接" width="1600" height="1013" decoding="async"></p><h2 id="好请求的五要素" tabindex="-1">好请求的五要素 <a class="header-anchor" href="#好请求的五要素" aria-label="Permalink to &quot;好请求的五要素&quot;">​</a></h2><p><img src="'+o+`" alt="好请求的五要素" width="1600" height="1013" loading="lazy" decoding="async"></p><p>跟 Grok Bot 交代任务，<strong>指令必须明确目标与工具范围</strong>，规范见 <a href="https://cursor.com/cn/docs/grok-bot" target="_blank" rel="noreferrer">《Grok Bot》</a> 文档。</p><ol><li><strong>动作具体单一</strong>。写明「抓取比对」或「起草外信」，别用「研究一下」，路径越短越省步数。</li><li><strong>限定数据来源</strong>。指定 Notion 页面、Slack #sales-leads 频道或网址，防全网乱搜。</li><li><strong>划清审批红线</strong>。读取比对自动跑；<strong>涉及发外信、在线支付或删改数据，必须暂停等审批</strong>。</li><li><strong>锁定交付形态</strong>。<strong>拒收口头汇报</strong>，要求在 <code>/workspace/leads/</code> 生成带链接的 Markdown 报告或 CSV 表格。</li><li><strong>定好报错规则与事实边界</strong>。区分推测与客观事实；遇到登录失效跳过并记录，<strong>禁止死循环重试</strong>。</li></ol><h2 id="附件规格与限制清单" tabindex="-1">附件规格与限制清单 <a class="header-anchor" href="#附件规格与限制清单" aria-label="Permalink to &quot;附件规格与限制清单&quot;">​</a></h2><p>上传规则见 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">《使用 Grok Bot》</a>。</p><h3 id="规格限制" tabindex="-1">规格限制 <a class="header-anchor" href="#规格限制" aria-label="Permalink to &quot;规格限制&quot;">​</a></h3><ul><li>桌面端每条<strong>限 6 个</strong>（超额放工作区）；图文音频限 25MB，视频限 200MB。</li><li>遇阻或报错，先在本地转 PDF、CSV 或图片再传。</li></ul><h3 id="交接与群聊" tabindex="-1">交接与群聊 <a class="header-anchor" href="#交接与群聊" aria-label="Permalink to &quot;交接与群聊&quot;">​</a></h3><ol><li><strong>拖入后别直接回车</strong>，写清各文件身份、关联逻辑与保护声明。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上传的 PDF 是已经签署的标准采购合同模板。上传的 Excel 是本月供应商提交的实际报价清单。</span></span>
<span class="line"><span>请对照合同模板中第 4 条关于各类物料的基准单价，逐行核验 Excel 里的实际报价。</span></span>
<span class="line"><span>标出单价超出基准价的所有条目，在附带的备忘中引用合同中的对应条款编号。</span></span>
<span class="line"><span>将核验结果另存为一份新的 Excel 表格，并输出一份简短的异常摘要。</span></span>
<span class="line"><span>请勿改动原始上传文件。</span></span></code></pre></div><ol start="2"><li>群聊中 Bot 间<strong>仅支持纯文本</strong>。下游要看附件必须私聊发它。</li></ol><h2 id="任务交付实用提示词库" tabindex="-1">任务交付实用提示词库 <a class="header-anchor" href="#任务交付实用提示词库" aria-label="Permalink to &quot;任务交付实用提示词库&quot;">​</a></h2><p>常用场景<strong>直接套模板</strong>，改改就能用。</p><ol><li><strong>调研外联</strong>：查线索备料，不直接发送。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从我们的 CRM 系统中获取本周销售管道的重点评审列表。</span></span>
<span class="line"><span>请跳过当前已经处于活跃跟进序列中的联系人。</span></span>
<span class="line"><span>在指定公开网页和已授权的 Slack 相关频道中，深入调研排名前五的重点账户，找出负责采购或技术的对口联系人。</span></span>
<span class="line"><span>参考我在系统中历史邮件的口吻，为这五位联系人分别起草个性化的初次外联邮件。</span></span>
<span class="line"><span>将草稿保存在系统草稿箱中，并在明天上午 9 点前在此对话中列出清单供我审批。未经我的明确确认，绝不向外发送任何邮件。</span></span></code></pre></div><ol start="2"><li><strong>附件核验</strong>：对齐多表并核查收支。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件中的 PDF 为《2026 年度差旅与报销政策细则》，CSV 表格为本月部门提交的待审批费用报销流水。</span></span>
<span class="line"><span>请逐项核对 CSV 中的每一笔申报项目：</span></span>
<span class="line"><span>1. 检查报销金额是否超过对应城市级别的住宿与餐饮标准。</span></span>
<span class="line"><span>2. 检查单笔超过 500 元的支出是否有对应的发票类别标记。</span></span>
<span class="line"><span>3. 提取所有不符合政策规定的异常申报，列明行号、申报人、金额、超标原因及违背的政策条款。</span></span>
<span class="line"><span>最后生成一份 Markdown 格式的核查报告，并列出通过与未通过的统计汇总。保持原始 CSV 文件不被改动。</span></span></code></pre></div><ol start="3"><li><strong>网站巡检</strong>：巡查页面并留存证据。</li></ol><details class="details custom-block"><summary>任务交付实用提示词库</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你负责检查我的网站运行状态。本次只访问我提供的以下三个页面：首页、最新更新日志页、用户注册页。</span></span>
<span class="line"><span>逐一核验各页面是否能正常打开、关键按钮是否响应、文本信息是否存在断链或明显过期内容。</span></span>
<span class="line"><span>排查过程中必须执行以下要求：</span></span>
<span class="line"><span>1. 发现任何显示异常或报错时，保存完整的页面 URL、检查时间戳以及当时的屏幕截图。</span></span>
<span class="line"><span>2. 区分页面直接看到的事实与你的推测，事实写在证据栏，分析写在备注栏。</span></span>
<span class="line"><span>3. 检查受阻或遇到需要验证码时，记录阻碍原因并继续检查下一个页面，不要重复尝试。</span></span>
<span class="line"><span>4. 检查结果报告保存在 /workspace/site-check/ 目录下，命名为 check-report.md。</span></span>
<span class="line"><span>你仅有只读检查与生成报告的权限，严禁更改后台设置或提交任何表单。</span></span></code></pre></div></details><ol start="4"><li><strong>方案排查</strong>：复杂操作前审逻辑防走偏。</li></ol><details class="details custom-block"><summary>任务交付实用提示词库</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我准备让你整理过去一个季度跨 Notion、Gmail 和 GitHub 的客户产品缺陷反馈。</span></span>
<span class="line"><span>在正式开始执行数据读取与整理之前，请先不要调用任何批量工具，先在对话中向我提交一份执行计划：</span></span>
<span class="line"><span>1. 列出你准备按顺序访问的系统、模块与具体检索词。</span></span>
<span class="line"><span>2. 说明你打算提取哪些关键字段，以及如何去重。</span></span>
<span class="line"><span>3. 标明整个流程中哪些环节可能涉及对外部状态的更改。</span></span>
<span class="line"><span>4. 说明你打算将阶段性文件保存在云电脑的哪个路径，以及遇到权限不足时如何处理。</span></span>
<span class="line"><span>我确认并批准你的计划后，你再开始执行。</span></span></code></pre></div></details><ol start="5"><li><strong>收件通报</strong>：提取要点并分类转交。</li></ol><details class="details custom-block"><summary>任务交付实用提示词库</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用已连接的邮箱插件，读取收件箱过去 24 小时内收到的全部新邮件。</span></span>
<span class="line"><span>按照以下业务逻辑进行分类处理：</span></span>
<span class="line"><span>1. 属于系统续费、订阅扣款账单的邮件，提取服务商、扣款金额与下次续费时间。</span></span>
<span class="line"><span>2. 属于用户直接提问或反馈 Bug 的邮件，提取发件人邮箱、问题概括与紧急程度。</span></span>
<span class="line"><span>3. 属于营销推广、垃圾资讯的邮件，直接归入忽略清单。</span></span>
<span class="line"><span>在当前会话中输出一份分栏概览：仅展示需我关注的账单与紧急反馈，并在每条记录后附带邮件主题与时间。</span></span>
<span class="line"><span>所有邮件保持未读或已读原状，未经审批严禁归档、删除或起草回复。</span></span></code></pre></div></details><h2 id="长期规则与单次任务-别把家规当家务" tabindex="-1">长期规则与单次任务：别把家规当家务 <a class="header-anchor" href="#长期规则与单次任务-别把家规当家务" aria-label="Permalink to &quot;长期规则与单次任务：别把家规当家务&quot;">​</a></h2><p><img src="`+i+'" alt="长期规则与单次任务：别把家规当家务" width="1600" height="1013" loading="lazy" decoding="async"></p><p><strong>分清长期规则与单次任务</strong>（参见 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">《使用 Grok Bot》</a>），别把临时参数写进长期设定，也别每次重打底线。</p><table tabindex="0"><thead><tr><th>类型</th><th>周期与设定</th><th>示例与限制</th></tr></thead><tbody><tr><td>长期规则</td><td>跨会话生效；Bot Details 配置或输入“请将这条作为你的长期规则记入你的记忆区”</td><td>权限红线、日期 YYYY-MM-DD</td></tr><tr><td>单次任务</td><td>单轮生效不沉淀；直接下达</td><td>处理 12 个账户或 3 个音频，提取十点会议清单</td></tr></tbody></table><p>所有 Bot 共用 <code>/workspace</code>（参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/Hfqxwy3zQiWkRPkVjRZcVCuHnbc" target="_blank" rel="noreferrer">《10 条必备经验，让你的 Grok Bot 变得更好用》</a>）。</p><p><strong>记忆不能替代业务系统</strong>，余额与库存必须回源拉取，严禁脑补。</p><h2 id="任务进行时的干预-停止、插话与审批" tabindex="-1">任务进行时的干预：停止、插话与审批 <a class="header-anchor" href="#任务进行时的干预-停止、插话与审批" aria-label="Permalink to &quot;任务进行时的干预：停止、插话与审批&quot;">​</a></h2><p><img src="'+r+`" alt="任务进行时的干预：停止、插话与审批" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="插话与停止" tabindex="-1">插话与停止 <a class="header-anchor" href="#插话与停止" aria-label="Permalink to &quot;插话与停止&quot;">​</a></h3><p>Bot 偏离目标时发普通消息就能<strong>即时插话</strong>，比如发“换成 2026 年 10 月更新后的新版规范再查”。</p><p>操作出错或遇高风险调用，在输入框发四个字停下。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>立即停止</span></span></code></pre></div><p><strong>停止只阻断未执行动作，绝不回滚已保存的文件或发出的 API 请求</strong>。停下后按三步排查。</p><ol><li>打开云电脑预览面板看状态。</li><li>清理半成品或错误写入。</li><li>缩小范围并明确边界后再重启。</li></ol><h3 id="审批与超时" tabindex="-1">审批与超时 <a class="header-anchor" href="#审批与超时" aria-label="Permalink to &quot;审批与超时&quot;">​</a></h3><p>开启 Auto-review 或触发高风险操作会弹出「评审操作」卡片（参见 <a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a>），包含三个选项。</p><ul><li>允许一次：仅批准本次，后续同类继续询问。</li><li>始终允许：加入白名单并不再提醒。</li><li>拒绝：彻底拦截该操作。</li></ul><table tabindex="0"><thead><tr><th>场景</th><th>等待机制</th><th>超时结果</th></tr></thead><tbody><tr><td>实时交互</td><td>挂起等待</td><td>持续等待直到点击处理</td></tr><tr><td>后台无人值守</td><td>约 10 分钟自动过期（Expired）</td><td><strong>不执行操作并结束任务</strong></td></tr></tbody></table><h3 id="凭据接管-action-needed" tabindex="-1">凭据接管（Action needed） <a class="header-anchor" href="#凭据接管-action-needed" aria-label="Permalink to &quot;凭据接管（Action needed）&quot;">​</a></h3><p>涉及密码、2FA，以及 CAPTCHA 或真实支付时弹出接管卡片，按三步操作。</p><ol><li>点击 <strong>Take over</strong> 在云电脑手动输入。</li><li>完成后点击 <strong>I&#39;m done</strong> 交还控制权。</li><li><strong>切勿在普通对话框输入明文密码</strong>。</li></ol><h2 id="语音交互-实时语音通话与语音听写的区分使用" tabindex="-1">语音交互：实时语音通话与语音听写的区分使用 <a class="header-anchor" href="#语音交互-实时语音通话与语音听写的区分使用" aria-label="Permalink to &quot;语音交互：实时语音通话与语音听写的区分使用&quot;">​</a></h2><p>Grok Bot 包含听写与通话<strong>两套不同的语音功能</strong>，详情参考 <a href="https://cursor.com/cn/help/grok-bot/voice-chat" target="_blank" rel="noreferrer">《与 Bot 语音聊天》</a> 与 <a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a>。</p><h3 id="两种模式对比" tabindex="-1">两种模式对比 <a class="header-anchor" href="#两种模式对比" aria-label="Permalink to &quot;两种模式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>触发与快捷键</th><th>输出与场景</th></tr></thead><tbody><tr><td>语音输入（听写）</td><td>桌面点「开始语音输入」，Mac 按 Cmd+D，Win/Linux 按 Ctrl+D，手机点「开始听写」</td><td>文字填入输入框，适合精改提示词或补参数</td></tr><tr><td>实时语音聊天</td><td><strong>清空输入框</strong>后点波形图标（Start voice chat）</td><td>双向实时通话，适合梳理思路或快速交接</td></tr></tbody></table><h3 id="开启步骤与避坑" tabindex="-1">开启步骤与避坑 <a class="header-anchor" href="#开启步骤与避坑" aria-label="Permalink to &quot;开启步骤与避坑&quot;">​</a></h3><ol><li>打开单个 Bot 对话。</li><li><strong>输入框必须彻底清空</strong>，残留空格或草稿都会隐藏波形图标。</li><li>点击波形图标，首次使用需允许麦克风权限。</li><li>显示 Connecting…（手机端 Calling…），Bot 主动开口即连通。</li></ol><h3 id="控制与硬性限制" tabindex="-1">控制与硬性限制 <a class="header-anchor" href="#控制与硬性限制" aria-label="Permalink to &quot;控制与硬性限制&quot;">​</a></h3><ul><li>通话中能静音，能看滚动字幕，也可调语速和音色；切屏查看资料时，点顶栏「返回语音聊天」即可切回。</li><li><strong>仅支持一对一单聊</strong>，群聊、多 Bot 群与「团队 Bot」均无法发起。</li><li><strong>同一时间只能维持一个通话</strong>，切到新 Bot 需确认「结束并聊天」。</li><li>挂断后自动生成 Voice chat 卡片记录总时长，点击查阅完整文本，后续任务在文字流继续推进。</li></ul><h2 id="常见失败写法与优化对照" tabindex="-1">常见失败写法与优化对照 <a class="header-anchor" href="#常见失败写法与优化对照" aria-label="Permalink to &quot;常见失败写法与优化对照&quot;">​</a></h2><ol><li><strong>收敛路径</strong>：没定范围与方法，Bot 会乱点控制台，<strong>甚至修改生产环境代码</strong>。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  帮我维护一下网站，看看有没有什么 Bug。</span></span></code></pre></div><p>改成限定页面与排查步骤：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  对站点清单（/workspace/sites.txt）中的三个静态展示页进行巡检。</span></span>
<span class="line"><span>  用云浏览器打开每个页面，检查控制台是否有 404 或 500 报错，检查顶部导航栏链接是否全部有效。</span></span>
<span class="line"><span>  将报错信息、对应页面 URL 及当时的屏幕截图写入 /workspace/logs/err-20261014.md。</span></span>
<span class="line"><span>  全程仅做只读检查，严禁点击任何带有提交或删除性质的表单按钮。</span></span></code></pre></div><ol start="2"><li><strong>审批边界</strong>：别给对外发送权限，一旦理解跑偏，<strong>容易给重要客户发错内容</strong>。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  读取 Gmail 里的未读邮件，重要的直接帮我回一下。</span></span></code></pre></div><p>关键节点让人来审批：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  读取 Gmail 中过去 12 小时的未读邮件。</span></span>
<span class="line"><span>  仅筛选出发件人属于我们现有企业客户、且正文包含售后或咨询诉求的邮件。</span></span>
<span class="line"><span>  根据产品常见问题手册，为每封邮件起草回复草稿并存入 Gmail 草稿箱。</span></span>
<span class="line"><span>  在当前对话中列出客户名称、邮件摘要与草稿正文，等待我的审批。未经我的明确确认，绝不点击发送。</span></span></code></pre></div><ol start="3"><li><strong>事实分立</strong>：提示词别夹带偏见，<strong>防止 Bot 迎合假设把小促销当成价格战</strong>。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  去看看竞品今天的动态，总结一下他们是不是要跟我们打价格战。</span></span></code></pre></div><p>要把客观数据和推测分开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  访问竞品官网的公开定价页与首页横幅，获取他们当下的方案价格表。</span></span>
<span class="line"><span>  对照我们在 /workspace/competitor/last-month-price.json 中记录的旧价格：</span></span>
<span class="line"><span>  1. 事实列：标出哪些 SKU 的标价发生了变动，变动金额是多少，附带页面截图与访问时间。</span></span>
<span class="line"><span>  2. 推测列：基于该降价是限时促销还是永久调价，给出你的分析理由。</span></span>
<span class="line"><span>  两部分内容必须分开分栏呈现，不得将分析推论当作已知事实。</span></span></code></pre></div><ol start="4"><li><strong>只读保护</strong>：没交代主从表与保留字段，<strong>原始数据极易被覆盖损坏</strong>。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  （直接拖入三个 Excel 表格）把这几个表整理一下。</span></span></code></pre></div><p>必须明确以哪张表为准、设为只读：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  上传的三个表格分别是 7 月、8 月和 9 月的销售明细。</span></span>
<span class="line"><span>  以「订单编号」为唯一主键进行数据去重合并：</span></span>
<span class="line"><span>  1. 字段统一保留：订单号、成交日期、客户名称、销售代表、成交金额。</span></span>
<span class="line"><span>  2. 生成一份全新的 Q3_sales_summary.csv 文件，保存在当前工作区。</span></span>
<span class="line"><span>  3. 保持我上传的原始 7、8、9 月表格内容与文件名完全不变。</span></span></code></pre></div><ol start="5"><li><strong>单一使命</strong>：别在一个 Bot 塞多个任务，既搞乱记忆，<strong>还会快速耗尽每周额度</strong>。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  你帮我写一篇关于新产品的推文，顺便把昨天的账目算了，然后再帮我看看竞品推特。</span></span></code></pre></div><p>拆成单任务分工流转：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  遵循一个 Bot 负责一项核心任务的原则。当前 Bot 仅承担社媒文案起草职责：</span></span>
<span class="line"><span>  依据 /workspace/product/spec.md 中的新功能说明，为 X 平台起草三条不同风格的发布文案。</span></span>
<span class="line"><span>  要求突出性能提升数据，字数控制在 280 字符以内。</span></span>
<span class="line"><span>  账目核算与竞品调研交由对应的专用 Bot 负责，不要在此会话中处理。</span></span></code></pre></div><h2 id="真实业务交接案例" tabindex="-1">真实业务交接案例 <a class="header-anchor" href="#真实业务交接案例" aria-label="Permalink to &quot;真实业务交接案例&quot;">​</a></h2><h3 id="网站日常巡检与证据留存" tabindex="-1">网站日常巡检与证据留存 <a class="header-anchor" href="#网站日常巡检与证据留存" aria-label="Permalink to &quot;网站日常巡检与证据留存&quot;">​</a></h3><p>站长 yishan 把巡检要求直接写成验收规范。工作目录严格限定在 <code>/workspace/site-check/</code>，只准检查首页、最新文章与订阅入口，严禁漫游爬取。</p><ul><li>报告必须留存完整链接、时间戳和当时截图。<strong>直接看到的报错算事实，排查原因算推测，必须分开记录。</strong></li><li>遇到登录失效或死链就记下缺口直接跳过，严禁反复死磕。具体做法见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/GBV8wdZOaijukikjO0pcYFWKnbg" target="_blank" rel="noreferrer">《如何在一个小时内深入使用 Grok Bot》</a>。</li></ul><h3 id="收件箱中转与业务分流" tabindex="-1">收件箱中转与业务分流 <a class="header-anchor" href="#收件箱中转与业务分流" aria-label="Permalink to &quot;收件箱中转与业务分流&quot;">​</a></h3><p>一泽Eze 专门设了一个收件箱 Bot 接管 Gmail，没给下游各个 Bot 分别开放邮箱权限。</p><ul><li><p>收到反馈邮件私聊转给「产品反馈 Bot」，账单转给「订阅管理 Bot」。</p></li><li><p>纯数值对比直接交给命令行脚本跑。<strong>只给 Bot 同步增量数据，能省下每周使用额度。</strong></p></li><li><p>高权限工具不要到处接，先用专职入口做初筛最稳当。</p><p>经验总结见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/Hfqxwy3zQiWkRPkVjRZcVCuHnbc" target="_blank" rel="noreferrer">《10 条必备经验，让你的 Grok Bot 变得更好用》</a>。</p></li></ul><h3 id="幕僚长摸底与建-bot" tabindex="-1">幕僚长摸底与建 Bot <a class="header-anchor" href="#幕僚长摸底与建-bot" aria-label="Permalink to &quot;幕僚长摸底与建 Bot&quot;">​</a></h3><p>CyrilXBT 先让幕僚长 Bot 读团队 Notion 与 Slack，排查出耗时最长、重复最高且卡点最多的前三项任务，分三步推进。</p><ol><li>幕僚长 Bot 手动带跑，人在旁监督输出质量。</li><li>确认无误后沉淀为技能，建独立专属 Bot。</li><li>最后配置定时自动跑。 **涉及发送、采购、发布或修改线上系统的节点，必须严格保留人工审批。</li></ol><p>** 完整教程见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/WGaCwZU71iHAGPkzjkLcahN2nHd" target="_blank" rel="noreferrer">《How to master Grok Bot in 16 minutes - Full Course｜CyrilXBT》</a>。</p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li><strong>传附件带说明</strong>：传多张图或两个以上表格时，<strong>务必写明用途</strong>，否则容易搞反主从关系。</li><li><strong>长期规则存入记忆</strong>：单次指令换会话就丢，底线规范要<strong>写进 Bot 详情的关于/职责</strong>或存入记忆。</li><li><strong>本地联动防休眠</strong>：纯云端合盖能跑，但联动本地电脑休眠会断连，记得<strong>检查电源与休眠设置</strong>。</li><li><strong>跨 Bot 传图走路径</strong>：群里 Bot 间只支持纯文本，传图必须<strong>存到 <code>/workspace/</code> 共享路径</strong>让对方读取。</li><li><strong>语音按钮消失先清空</strong>：输入框留有未清空的文字或空格时波形按钮会隐藏，<strong>彻底清空输入框</strong>即可恢复。</li><li><strong>高危操作选允许一次</strong>：发邮件或删改数据别选「始终允许」，稳定跑数周前，<strong>坚持选「允许一次」</strong>。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li>去 <code>/workspace/</code> 或指定目录核验文件，<strong>确认能正常预览且无乱码</strong>，别只看临时文本。</li><li>抽 2 到 3 处核心数据点开链接或截图，防模型凭空臆测。</li><li>翻调用日志，<strong>确认没私自外发通信，也没改配置或覆盖原文件</strong>。</li><li>分清事实与推测，页面原话放事实区，推论建议放备注区，混淆的当场纠正。</li><li>查异常清单，<strong>遇到失效网页或缺字段要记明原因并跑完</strong>，别一报错就中断。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot" target="_blank" rel="noreferrer">《Grok Bot》</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">《使用 Grok Bot》</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/voice-chat" target="_blank" rel="noreferrer">《与 Bot 语音聊天》</a></li><li>社区文章：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/GBV8wdZOaijukikjO0pcYFWKnbg" target="_blank" rel="noreferrer">《如何在一个小时内深入使用 Grok Bot》</a></li><li>社区文章：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Hfqxwy3zQiWkRPkVjRZcVCuHnbc" target="_blank" rel="noreferrer">《10 条必备经验，让你的 Grok Bot 变得更好用》</a></li><li>社区文章：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/WGaCwZU71iHAGPkzjkLcahN2nHd" target="_blank" rel="noreferrer">《How to master Grok Bot in 16 minutes - Full Course｜CyrilXBT》</a></li></ul>`,95)])])}const f=s(p,[["render",c]]);export{m as __pageData,f as default};
